          "end": "2024-12-31"
        },
        "to_period": {
          "label": "FY2025",
          "start": "2025-01-01",
          "end": "2025-12-31"
        },
        "value": "4.29",
        "unit": "percent"
      }
    },
    {
      "claim_id": "C2",
      "text": "Consolidated Operating Profit decreased by 14.70% (calculated from $13,072 million to $11,151 million), compared to the filing's reported rounded decrease of 15%.",
      "evidence_ids": [
        "EP_0014_E02"
      ],
      "check_spec": {
        "kind": "percentage_change",
        "from_fact_id": "EP_0014_F04",
        "to_fact_id": "EP_0014_F03",
        "metric": "operating_profit",
        "from_period": {
          "label": "FY2024",
          "start": "2024-01-01",
          "end": "2024-12-31"
        },
        "to_period": {
          "label": "FY2025",
          "start": "2025-01-01",
          "end": "2025-12-31"
        },
        "value": "-14.70",
        "unit": "percent"
      }
    },
    {
      "claim_id": "C3",
      "text": "The decrease in operating profit was primarily due to unfavorable manufacturing costs of $2,148 million and unfavorable price realization of $817 million, partially offset by the profit impact of higher sales volume of $1,218 million (Item 7, EP_0014_E02).",
      "evidence_ids": [
        "EP_0014_E02"
      ],
      "check_spec": null
    },
    {
      "claim_id": "C4",
      "text": "The operating profit margin declined from 20.2 percent in 2024 to 16.5 percent in 2025 (Item 7, EP_0014_E02).",
      "evidence_ids": [
        "EP_0014_E02"
      ],
      "check_spec": null
    },
    {
      "claim_id": "C5",
      "text": "The SEGMENT_33 segment's profit decreased by 24.17% (calculated from $6,165 million to $4,675 million), compared to the filing's reported rounded decrease of 24%.",
      "evidence_ids": [
        "EP_0014_E02"
      ],
      "check_spec": {
        "kind": "percentage_change",
        "from_fact_id": "EP_0014_F06",
        "to_fact_id": "EP_0014_F05",
        "metric": "construction_industries_profit",
        "from_period": {
          "label": "FY2024",
          "start": "2024-01-01",
          "end": "2024-12-31"
        },
        "to_period": {
          "label": "FY2025",
          "start": "2025-01-01",
          "end": "2025-12-31"
        },
        "value": "-24.17",
        "unit": "percent"
      }
    }
  ],
  "rationale": "While historical results show revenue growth, the significant profit decline and margin compression, combined with trade policy risks noted in Item 1A, present material downside risks to future profitability and share price performance."
}

